import{_ as p,a0 as l,w as a,s as d,ao as n,I as o,x as s,a1 as i,A as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"GNOME 搜索功能的一些小技巧 | LCTT x X-CMD","titleTemplate":false,"description":"GNOME 搜索功能的一些小技巧 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"GNOME 搜索功能的一些小技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"GNOME 搜索功能的一些小技巧 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions","title":"GNOME 搜索功能的一些小技巧","tag":"202112","desc":""},"relativePath":"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions.md","filePath":"[post].md"}'),m={name:"202112/20211216 Hide or Add Specific Folders From GNOME Search Results in Ubuntu and Other Linux Distributions.md"};function f(u,t,g,b,T,h){const e=l("Link");return a(),d("div",null,[t[33]||(t[33]=n('<h1 id="gnome-搜索功能的一些小技巧" tabindex="-1">GNOME 搜索功能的一些小技巧 <a class="header-anchor" href="#gnome-搜索功能的一些小技巧" aria-label="Permalink to “GNOME 搜索功能的一些小技巧”">​</a></h1><p>你可能已经注意到，当你在 GNOME 菜单/活动区搜索某样东西时，它也会显示名称与搜索词相匹配的文件，以及已安装的应用。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202112/25/115842tf8jjgn4ttz7nf4m.jpg" alt=""></p><p>这是个很方便的功能。如果你记得文件名，甚至是它的一部分，你可以很容易地搜索到它，只需按下 <code>Super</code> 键（<code>Windows</code> 键）并输入文件名就可以打开它。</p><p>但是，围绕这个搜索功能，有一些你可能不知道或从未关心过的小问题。</p><p>在这篇文章中，我将分享你如何控制 GNOME 搜索功能，从搜索选项中添加或隐藏文件夹，以及完全禁用它。</p>',6)),o("p",null,[t[1]||(t[1]=s("注意：这专门针对使用 GNOME 的发行版。请 ",-1)),i(e,{href:"https://itsfoss.com/find-desktop-environment/"},{default:r(()=>[...t[0]||(t[0]=[s("确认你使用的是哪种桌面环境",-1)])]),_:1}),t[2]||(t[2]=s("，确保是 GNOME。",-1))]),t[34]||(t[34]=o("h3",{id:"文件搜索的默认位置",tabindex:"-1"},[s("文件搜索的默认位置 "),o("a",{class:"header-anchor",href:"#文件搜索的默认位置","aria-label":"Permalink to “文件搜索的默认位置”"},"​")],-1)),o("p",null,[t[4]||(t[4]=s("GNOME 的搜索功能使用了一个叫做 ",-1)),i(e,{href:"https://wiki.gnome.org/Projects/Tracker/Documentation/GettingStarted"},{default:r(()=>[...t[3]||(t[3]=[s("Tracker Miner FS",-1)])]),_:1}),t[5]||(t[5]=s(" 的工具。请不要被 “tracker” 和 “miner” 这样的术语吓到。它不是在监视你，也不是在你的系统上挖掘加密货币。它的基本功能是作为一个搜索引擎和数据库，为你提供即时搜索结果。",-1))]),t[35]||(t[35]=n('<p>默认情况下，文件索引发生在元文件夹，如文档、音乐、图片和视频目录及其子目录。主页和下载文件夹中的文件也会被索引，但不包括其子目录中的文件。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-default-search-location.png?resize=800%2C533&amp;ssl=1" alt="Default locations for file search"></p><p>如果你在你的主文件夹中创建了一些新的目录，这些文件将不会被索引。</p><p>然而，最近访问的文件也会被自动编入索引。如果你最近打开了一个文件，它将被添加到 “最近的文件” 中，并将出现在搜索结果中，而不管它在什么地方。</p><p>如果你还不知道的话，你可以在文件管理器中看到你最近访问的文件：</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/access-recent-files-gnome-linux.png?resize=735%2C414&amp;ssl=1" alt="Accessing recent files in GNOME file manager"></p><h3 id="在搜索结果中添加一个文件夹的内容" tabindex="-1">在搜索结果中添加一个文件夹的内容 <a class="header-anchor" href="#在搜索结果中添加一个文件夹的内容" aria-label="Permalink to “在搜索结果中添加一个文件夹的内容”">​</a></h3><p>假设你在你的主目录中为编码项目创建了一个文件夹。这些文件不会被索引，也不会出现在搜索结果中（除非你通过双击打开了一个文件，并且它被添加到最近的文件中）。</p><p>要在搜索结果中添加自定义文件夹中的文件，你可以将该文件夹添加到搜索位置。</p><p>通过在菜单/活动区搜索打开 “设置” 应用。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2020/04/settings-search-ubuntu-20-04.jpg?resize=800%2C230&amp;ssl=1" alt="Search for settings application"></p><p>从左侧边栏进入 “搜索” 选项，点击顶部的“搜索位置”选项。在弹出的窗口中，进入 “其他” 标签，点击 “+” 符号。它将打开文件浏览器，你可以添加你想要的文件夹。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/gnome-add-search-location.png?resize=800%2C525&amp;ssl=1" alt="Adding a custom folder content to search"></p><p>如果你在刚刚添加的文件夹中搜索一个文件名进行测试，你现在应该在搜索结果中看到它。它应该是即时的，但如果不是，请尝试注销或重启系统。</p><h3 id="从搜索结果中隐藏一个文件夹" tabindex="-1">从搜索结果中隐藏一个文件夹 <a class="header-anchor" href="#从搜索结果中隐藏一个文件夹" aria-label="Permalink to “从搜索结果中隐藏一个文件夹”">​</a></h3><p>如果你不希望某个特定文件夹的文件出现在搜索结果中，你可以隐藏它。</p><p>如果你不希望在搜索中出现图片、文档、视频等元文件夹的内容，你可以从搜索位置设置中禁用它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/disable-folders-from-search.png?resize=800%2C533&amp;ssl=1" alt="Disable meta folders from the search"></p><p>如果你只想让文档下的某个文件夹的内容不出现在搜索结果中，你只需要在该文件夹中创建一个名为 <code>.nomedia</code> 的新文件。你也可以将该文件命名为 <code>.git</code>、<code>.trackerignore</code> 或 <code>.hg</code>。</p><p><img src="https://i1.wp.com/itsfoss.com/wp-content/uploads/2021/12/hide-specific-folder-from-search-results.png?resize=751%2C382&amp;ssl=1" alt="Hide specific folder from search results by creating file named .nomedia or .hg or .git"></p>',20)),o("p",null,[t[8]||(t[8]=s("如果你在鼠标右键中没有看到创建新文件的选项，你必须做一些调整来增加 ",-1)),i(e,{href:"https://itsfoss.com/add-new-document-option/"},{default:r(()=>[...t[6]||(t[6]=[s("在右键上下文菜单中创建新文件选项",-1)])]),_:1}),t[9]||(t[9]=s("。还要注意的是，任何名称中以 ",-1)),t[10]||(t[10]=o("code",null,".",-1)),t[11]||(t[11]=s(" 开头的文件都会被隐藏起来，不能被正常查看。要 ",-1)),i(e,{href:"https://itsfoss.com/hide-folders-and-show-hidden-files-in-ubuntu-beginner-trick/"},{default:r(()=>[...t[7]||(t[7]=[s("切换显示隐藏文件",-1)])]),_:1}),t[12]||(t[12]=s("，按 ",-1)),t[13]||(t[13]=o("code",null,"Ctrl+H",-1)),t[14]||(t[14]=s(" 键。",-1))]),t[36]||(t[36]=n('<p>这种隐藏可能不会立即生效，因为该文件可能已经被索引了。你可能必须注销或重启才能看到效果。</p><p>如果你手动访问一个文件，它将被添加到最近的文件中，并且会出现在搜索结果中，尽管文件夹中的文件被忽略了。</p><p>你可以从 “设置 -&gt; 隐私 -&gt; 文件历史 &amp; 垃圾箱” 删除最近的文件历史或完全禁用它（如果你想的话）。不过我认为没有必要，所以在这里你自己决定吧。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2021/12/clear-or-disable-file-history-gnome-linux.png?resize=800%2C389&amp;ssl=1" alt="Clear or disable file access history in GNOME"></p><h3 id="禁用所有文件的搜索结果" tabindex="-1">禁用所有文件的搜索结果 <a class="header-anchor" href="#禁用所有文件的搜索结果" aria-label="Permalink to “禁用所有文件的搜索结果”">​</a></h3><p>如果你不希望任何文件出现在搜索结果中，你可以在搜索设置中完全禁用对文件的搜索。</p><p><img src="https://i2.wp.com/itsfoss.com/wp-content/uploads/2021/12/disable-search-for-files-gnome.png?resize=800%2C475&amp;ssl=1" alt="Disable search results for all files"></p><p>你应该通过点击顶部的搜索切换按钮完全禁用搜索功能，它可能会干扰 GNOME 桌面环境的正常功能。</p><p>关于它的更多细节可以在 [项目主页] 中找到。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>这里的 <em>讨论的是文件搜索</em>。GNOME 桌面也可以在日历、字符映射和其他一些程序中进行搜索。你可以禁用或启用可用的搜索选项，但我们这篇不针对这些。</p>',11)),o("p",null,[t[16]||(t[16]=s("我希望你觉得这个快速提示对 ",-1)),i(e,{href:"https://itsfoss.com/gnome-tricks-ubuntu/"},{default:r(()=>[...t[15]||(t[15]=[s("定制你的 GNOME 体验",-1)])]),_:1}),t[17]||(t[17]=s(" 有帮助。如果你知道其他一些你想让别人知道的技巧，请在评论中与我们分享。",-1))]),t[37]||(t[37]=o("hr",null,null,-1)),o("p",null,[t[19]||(t[19]=s("via: ",-1)),i(e,{href:"https://itsfoss.com/control-gnome-file-search/"},{default:r(()=>[...t[18]||(t[18]=[s("https://itsfoss.com/control-gnome-file-search/",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=s("作者：",-1)),i(e,{href:"https://itsfoss.com/author/abhishek/"},{default:r(()=>[...t[20]||(t[20]=[s("Abhishek Prakash",-1)])]),_:1}),t[25]||(t[25]=s(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[21]||(t[21]=[s("lujun9972",-1)])]),_:1}),t[26]||(t[26]=s(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:r(()=>[...t[22]||(t[22]=[s("geekpi",-1)])]),_:1}),t[27]||(t[27]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[23]||(t[23]=[s("wxy",-1)])]),_:1})]),o("p",null,[t[30]||(t[30]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[28]||(t[28]=[s("LCTT",-1)])]),_:1}),t[31]||(t[31]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:r(()=>[...t[29]||(t[29]=[s("Linux中国",-1)])]),_:1}),t[32]||(t[32]=s(" 荣誉推出",-1))])])}const M=p(m,[["render",f]]);export{x as __pageData,M as default};
